{"concepto": "descomposición autoregresiva (autoregressive decomposition)", "enunciado": "p(x_{1:L})=\\prod_{t=1}^{L}p(x_t\\mid x_{<t})", "problema": "factorizar una distribución conjunta en probabilidades condicionales secuenciales", "limite": "requiere orden temporal definido; el modelo generativo debe muestrear secuencialmente", "patron": "dividir un problema de optimización global en decisiones locales encadenadas donde cada paso solo depende del pasado", "linea": 73}
{"concepto": "caché de claves-valores (KV cache)", "enunciado": "M_{\\mathrm{KV}}\\approx 2L\\,n_\\ell n_{kv}d_h b", "problema": "reducir recálculos guardando representaciones key-value de tokens históricos", "limite": "la memoria crece linealmente con L (largo de contexto); limitada por ancho de banda HBM", "patron": "guardar productos intermedios costosos para reutilización, a cambio de crecimiento de estado", "linea": 102}
{"concepto": "modelo de espacio de estados lineal (State Space Model, SSM)", "enunciado": "h_t=A_t h_{t-1}+B_t x_t, \\quad y_t=C_t^{\\top}h_t", "problema": "comprimir la historia de tokens en un estado de tamaño fijo actualizado iterativamente", "limite": "estado de dimensión N fija; compresión irreversible; difícil recuperar detalles específicos", "patron": "evolución de estado mediante transformación afín que integra entrada actual y estado anterior", "linea": 120}
{"concepto": "expansión de estado (state expansion)", "enunciado": "pasar de escalar a N-dimensional per-channel state, forma conceptual B×D×N", "problema": "aumentar capacidad de memoria más allá de un único escalar por entrada", "limite": "limitado por memoria HBM en materialización; no garantiza que N dimensiones = N tokens separables", "patron": "incrementar dimensionalidad de representación comprimida para capturar múltiples características temporales", "linea": 162}
{"concepto": "selectividad en SSM (Selective SSM)", "enunciado": "h_t=A(x_t)h_{t-1}+B(x_t)x_t donde A,B dependen de x_t", "problema": "permitir que el modelo decida dinámicamente cuánta información anterior retener vs olvidar", "limite": "no garantiza lógica simbólica; requiere supervisión y capacidad de estado adecuadas", "patron": "hacer que los coeficientes de transformación dependan de la entrada actual para adaptar comportamiento", "linea": 180}
{"concepto": "exploración asociativa paralela (associative scan / parallel prefix scan)", "enunciado": "(A_2,b_2)\\circ(A_1,b_1)=(A_2A_1,\\;A_2b_1+b_2), \\text{ es asociativa}", "problema": "entrenar recurrencias lineales con paralelismo en profundidad logarítmica en lugar de O(L) pasos", "limite": "válido solo para actualizaciones afines/lineales; no para gating no-lineal", "patron": "descomponer secuencia de operaciones asociativas en árbol de reducción paralela", "linea": 207}
{"concepto": "máquina de estado autoregresiva (autoregressive state machine)", "enunciado": "s_t=U_\\theta(s_{t-1},x_t), \\quad p(x_{t+1}\\mid x_{\\le t})=R_\\theta(s_t)", "problema": "abstraer cualquier modelo generativo secuencial como máquina de estados persistente", "limite": "descripción puramente formal; no determina si s_t es cache distribuido o comprimido", "patron": "todo proceso generativo mantiene estado implícito que persiste entre pasos de tiempo", "linea": 261}
{"concepto": "cuello de botella informativo (information bottleneck)", "enunciado": "s_t con capacidad limitada vs x_{≤t} con información creciente; U_θ debe elegir qué retener", "problema": "explicar por qué estados comprimidos sacrifican retrieval exacto pero ganan state tracking", "limite": "no cuantifica cuánta información se pierde; depende de task y update rule", "patron": "una restricción en transmisión de información obliga a seleccionar qué información conservar", "linea": 289}
{"concepto": "arquitectura híbrida (hybrid model)", "enunciado": "intercalación de capas recurrentes/lineales y capas de attention en profundidad", "problema": "combinar ventajas de compresión online con acceso exacto token-resolution", "limite": "ratio óptimo de SSM:attention depende de width, state size, datos y tarea", "patron": "dividir trabajo entre múltiples primitivos especializados en diferentes funciones", "linea": 304}
{"concepto": "patchificación de visión (vision patchification)", "enunciado": "L_{\\mathrm{vision}}=\\frac{H}{P}\\frac{W}{P} donde P es patch size", "problema": "transformar imagen de alta resolución en secuencia de patches de tamaño fijo", "limite": "patch size pequeño → más tokens → O(L²) attention; grande → pérdida de detalles", "patron": "segmentar datos 2D de alta dimensión en unidades discretas de tamaño fijo", "linea": 355}
{"concepto": "codificación de pares de bytes (Byte Pair Encoding, BPE)", "enunciado": "combinar pares de símbolos frecuentes iterativamente para formar tokens más largos", "problema": "construir unidades composables de nivel intermedio entre caracteres y palabras", "limite": "heurística fija offline; no adapt
a a cambios de contexto; inyecta boundary bias", "patron": "merging bottom-up de elementos frequentes para construir unidades composables", "linea": 363}
{"concepto": "bits por byte (bits per byte, BPB)", "enunciado": "\\mathrm{BPB}=-\\frac{1}{L\\ln 2}\\sum_{t=1}^{L}\\ln p(x_t\\mid x_{<t})", "problema": "medir perplexity en nivel byte evitando dependencia de tokenizer specifico", "limite": "aplicable solo a byte-level; afectado por dataset, context length, model budget", "patron": "neglog promedio de probabilidad condicional, normalizado por cantidad de elementos", "linea": 389}
{"concepto": "segmentación dinámica (dynamic chunking)", "enunciado": "r_t=\\sigma(w^\\top z_t+b), m_t\\sim\\operatorname{Route}(r_t), c_j=\\operatorname{Pool}\\{z_t:t\\in I_j\\}", "problema": "aprender límites de segmentación context-dependent en lugar de tokenizer offline", "limite": "optimización discreta difícil; riesgo de collapse; requiere smoothing y normalization", "patron": "predecir puntos de decisión y aplicar agregación selectiva en regiones delimitadas", "linea": 450}
{"concepto": "jerarquía en reloj de arena (H-Net hourglass hierarchy)", "enunciado": "encoder fino → chunking → main model → dechunking → decoder, múltiples etapas", "problema": "aprender múltiples niveles de abstracción comprimiendo, modelando y expandiendo", "limite": "routing discreto es difícil de optimizar; sin validación a escala frontier", "patron": "alternar fases de compresión selectiva, procesamiento comprimido, y expansión informada", "linea": 471}
{"concepto": "ley de potencia de escala (power law scaling exponent)", "enunciado": "\\mathcal{L}(C)\\approx \\mathcal{L}_\\infty + aC^{-\\alpha}", "problema": "describir cómo cambia una métrica (loss) con inversión de recursos (compute)", "limite": "válida en rango limitado; extrapolación más allá requiere validación; depende de task", "patron": "relación de potencia inversa entre cantidad de recurso y métrica de rendimiento", "linea": 508}
{"concepto": "mecanismo de atención softmax (softmax attention)", "enunciado": "\\operatorname{Attn}(q,K,V)=\\sum_{i=1}^{L}\\alpha_i v_i, \\quad \\alpha_i=\\frac{\\exp(q^\\top k_i/\\sqrt d)}{\\sum_j\\exp(q^\\top k_j/\\sqrt d)}", "problema": "computar combinación convexa de valores ponderada por similitud query-key", "limite": "requiere almacenar K y V (O(L) memoria); O(L²) pairwise comparisons en attention", "patron": "normalizar matriz de puntuación para producir pesos de combinación convexa", "linea": 415}
{"concepto": "factorización de eficiencia de sistema (system efficiency factorization)", "enunciado": "\\text{efficiency}=\\frac{\\text{FLOPs}}{\\text{dollars}}\\times\\frac{\\text{capabilities}}{\\text{FLOPs}}", "problema": "optimizar conversión de recursos económicos a capacidades, identificando dos componentes", "limite": "ambos factores varían con hardware, kernel, optimizer; no es simplemente minimizar FLOPs", "patron": "descomponer métrica compuesta en factores independientes mejorables separadamente", "linea": 607}
